1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const TYPES_INCLUDED_IN_BASE_BONUS = 3;
9	const SPHINX_POINTS = 1;
10	const BASE_BONUS = 1;
11	const BONUS_PER_EXTRA_TYPE = 2;
12	
13	const countDistinctMonsterTypes = (army: Card[]): number =>
14	  new Set(army.map((card) => card.monster)).size;
15	
16	const bonusForVariety = (distinctTypeCount: number): number => {
17	  const typesBeyondBase = distinctTypeCount - TYPES_INCLUDED_IN_BASE_BONUS;
18	  return typesBeyondBase > 0
19	    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
20	    : BASE_BONUS;
21	};
22	
23	const countCardsOfType = (army: Card[], monster: string): number =>
24	  army.filter((card) => card.monster === monster).length;
25	
26	export const scoreArmy = (army: Card[]): number => {
27	  const sphinxCount = countCardsOfType(army, SPHINX);
28	
29	  // A Sphinx counts the types among the OTHER cards — the ones it is looking
30	  // at. Sphinx is one of those types whenever a second Sphinx is present.
31	  const otherCards = army.filter((card) => card.monster !== SPHINX);
32	  const typesSeenByEachSphinx =
33	    countDistinctMonsterTypes(otherCards) + (sphinxCount > 1 ? 1 : 0);
34	
35	  return sphinxCount * (SPHINX_POINTS + bonusForVariety(typesSeenByEachSphinx));
36	};
