const isSphinx = (card: Card): boolean => card.monster === SPHINX;

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;

  // A Sphinx counts the types among the OTHER cards — the ones it is looking
  // at. Sphinx is one of those types whenever a second Sphinx is present.
  const cardsSeenByASphinx = army.filter((card) => !isSphinx(card));
  const typesSeenByEachSphinx =
    countDistinctMonsterTypes(cardsSeenByASphinx) + (sphinxCount > 1 ? 1 : 0);
